counter.v<pre><code>module counter #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    output reg  [WIDTH-1:0] count
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count &lt;= '0;
        else
            count &lt;= count + 1'b1;
    end
endmodule
